update public.fields set verification_status='verified_against_standard', verification_quote='Confidential and sensitive information obtained or created during validation/verification activities is safeguarded and not inappropriately or carelessly handled or disclosed. 4.6.2 Information is not used inappropriately for personal gain by those involved in the validation/verification process or in a manner detrimental to the legitimate interest of the client or responsible party. — printed p.13 (PDF p.19)', verification_note='VA-verified 2026-09-08 (§4.6.1 and §4.6.2, printed p.13 (PDF p.19) — gate CR-010 is severity=BLOCK on this field, but §4.6 contains no "shall" — see the STAGED file (block on non-shall text)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='f92a99ee-da48-45b1-88b0-f986a0110fd0' and verification_status not in ('verified_against_standard','corrected');
-- integrity_demonstrated
update public.fields set verification_status='verified_against_standard', verification_quote='Integrity is demonstrated through behaviour, trust, honesty, working with diligence and responsibility, observing the legal provisions (regulatory and contractual), maintaining confidentiality and making disclosures expected by the legal provisions (regulatory and contractual) and the profession throughout the validation or verification process. — printed p.13 (PDF p.19)', verification_note='VA-verified 2026-09-08 (§4.7, printed p.13 (PDF p.19) — gate CR-011 is severity=BLOCK on this field, but §4.7 contains no "shall" — see the STAGED file (block on non-shall text)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='0972f1f3-70a1-4135-a65b-b19d8492a351' and verification_status not in ('verified_against_standard','corrected');
-- fair_presentation
update public.fields set verification_status='verified_against_standard', verification_quote='Validation/verification activities, findings, conclusions and assurance, including significant problems encountered during the validation/verification activities are truthfully and accurately reflected, and all unresolved or divergent views between the validation/verification body and the client or responsible party are truthfully and accurately disclosed. — printed p.13 (PDF p.19)', verification_note='VA-verified 2026-09-08 (§4.8, printed p.13 (PDF p.19)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='6a68ad6c-9674-4ff6-aeda-92d5f535e89d' and verification_status not in ('verified_against_standard','corrected');
-- due_professional_care
update public.fields set verification_status='verified_against_standard', verification_quote='Due professional care, judgement and competence is exercised in accordance with the risk attributed to the tasks performed and the confidence that is placed upon the validation/verification process by clients and intended users. — printed p.13 (PDF p.19)', verification_note='VA-verified 2026-09-08 (§4.9, printed p.13 (PDF p.19)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='f1ccd7a8-6640-43db-b009-755dba3762e3' and verification_status not in ('verified_against_standard','corrected');
-- professional_judgement
update public.fields set verification_status='verified_against_standard', verification_quote='Professional judgement draws meaningful and accurate conclusions, opinions and interpretations that are based on observations, knowledge, experience, literature, objective evidence and other sources of information, and demonstration of professional scepticism. — printed p.13 (PDF p.19)', verification_note='VA-verified 2026-09-08 (§4.10, printed p.13 (PDF p.19)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='611af43e-c24a-44c5-9739-23d1e894f724' and verification_status not in ('verified_against_standard','corrected');

