-- vv_programme
update public.fields set verification_status='verified_against_standard', verification_quote='set of rules and procedures that describes declared sustainability information (3.1.4), identifies the specified requirements (3.2.3) and criteria (3.2.2), and provides the methodology for performing validation (3.2.6)/verification (3.2.7) — printed p.4 (PDF p.10)', verification_note='VA-verified 2026-09-08 (§3.2.1, printed p.4 (PDF p.10)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='bc943800-537f-44e4-a02f-536f7753a69d' and verification_status not in ('verified_against_standard','corrected');
