-- programme_suitability_confirmed
update public.fields set verification_status='verified_against_standard', verification_quote='The validation/verification body shall evaluate the suitability of validation/verification programmes by considering whether they include the following elements: a) description of the declared sustainability information which is to be confirmed through validation/verification (see 7.2); [...] f) specification of the category of deliverable as the outcome of the validation/verification (see 7.6). — printed p.18 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§7.1.2 a) to f), printed p.18 (PDF p.24) — printed elements b) to e) elided for length; the boolean stands for all six a) to f). §7.1.2 is a "shall", so block gate CR-014 is defensible) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='ef03fb3a-ff06-48e5-98cc-fb5516ab9bf9' and verification_status not in ('verified_against_standard','corrected');
-- decision_to_proceed
update public.fields set verification_status='verified_against_standard', verification_quote='After evaluating the suitability of a validation/verification programme, validation/verification bodies shall decide whether to proceed with validation or verification activities. — printed p.18 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§7.1.3, printed p.18 (PDF p.24) — §7.1.3 is a "shall" but NO gate reads this field — CR-014 names §7.1.3 in its clause_reference yet tests only the §7.1.2 boolean (see the STAGED file)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='038301cb-cee6-407b-93ac-f302fe5f4b4d' and verification_status not in ('verified_against_standard','corrected');
-- information_description_complete
update public.fields set verification_status='verified_against_standard', verification_quote='The validation/verification body shall ensure that the declared sustainability information to be validated/verified is clearly described in terms of: a) identification for the scope of validation/verification; b) the format and media in which the declared sustainability information is to be provided (e.g. report, statement, declaration, plan, consolidated data); c) any consultation process performed by the responsible party; [...] d) the intended users and their purpose, including if any intended user is representing interested parties; — printed p.18 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§7.2 a) to g), printed p.18 (PDF p.24) — printed items e) to g) elided for length; the boolean stands for all of a) to g). §7.2 is a "shall", so block gate CR-015 is defensible) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='eaca8d48-49e7-4e14-a2e9-56b1b87a411d' and verification_status not in ('verified_against_standard','corrected');
-- information_boundaries
