-- scope_of_vv
update public.fields set verification_status='verified_against_standard', verification_quote='scope of validation/verification identification of: — the declared sustainability information (3.1.4) to be the object of validation (3.2.6) or verification (3.2.7), including the boundaries of the declared sustainability information; — the applicable validation/verification programme (3.2.1); — the specified requirements (3.2.3) and criteria (3.2.2) to which the declared sustainability information is validated/verified — printed p.7 (PDF p.13)', verification_note='VA-verified 2026-09-08 (§3.2.20, printed p.7 (PDF p.13)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='dc80868c-3857-46f2-bb23-ea8e1f9d8b57' and verification_status not in ('verified_against_standard','corrected');
-- requirements_criteria_identified
update public.fields set verification_status='verified_against_standard', verification_quote='The validation/verification body shall ensure that the specified requirements and criteria against which the declared sustainability information is to be validated/verified are identified in terms of: a) intended users and their purpose and whether any intended users represent interested parties; b) sustainability impacts and dependencies; c) being suitable to be used in the validation/verification of the declared sustainability information; [...] h) reference to relevant regulations, standards, specifications and other normative documents. — printed p.19 (PDF p.25)', verification_note='VA-verified 2026-09-08 (§7.3.1 a) to h), printed p.19 (PDF p.25) — printed items d) to g) elided for length; the boolean stands for all of a) to h). §7.3.1 is a "shall", so block gate CR-016 is defensible) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='1964e1a8-06ca-4133-9fcc-813d5d5a94bd' and verification_status not in ('verified_against_standard','corrected');
-- criteria_availability
update public.fields set verification_status='verified_against_standard', verification_quote='The validation/verification body shall clarify whether the responsible party has made available to intended users the specified requirements and criteria. Specified requirements and criteria can be made available to the intended users in one or more of the following ways: a) publicly; b) through inclusion in a clear manner in the presentation of the sustainability information; c) through inclusion in a clear manner in the assurance opinion. — printed p.19 (PDF p.25)', verification_note='VA-verified 2026-09-08 (§7.3.2 a) to c), printed p.19 (PDF p.25) — the printed duty is to CLARIFY WHETHER the criteria were made available, and the printed list is "one or more of the following ways" — the encoded field is a single-select enum with no "not made available" member, so a legitimate negative outcome cannot be recorded and block gate CR-017 (criteria_availability IS NOT NULL) cannot then be cleared truthfully (see the STAGED file)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='d82fa261-5c03-40b3-8caf-f59fec96f831' and verification_status not in ('verified_against_standard','corrected');
-- criteria_suitability_confirmed
update public.fields set verification_status='verified_against_standard', verification_quote='As part of the pre-engagement, the validation/verification body shall determine whether the specified requirements and criteria are suitable to be used as the basis for the validation/verification activity. | a) preconditions regarding the suitability of criteria (i.e. relevance, completeness, reliability, neutrality, understandability); — printed pp.19, 20 (PDF pp.25, 26)', verification_note='VA-verified 2026-09-08 (§7.3.3 and §7.4.2 a), printed pp.19, 20 (PDF pp.25, 26)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='44825e59-13fd-477c-8114-1e41c3fca8ed' and verification_status not in ('verified_against_standard','corrected');
-- engagement_scope_agreed
update public.fields set verification_status='verified_against_standard', verification_quote='At the process step of engagement, the validation/verification body shall agree with the client the scope of validation/verification, and the specified requirements and criteria. — printed p.19 (PDF p.25)', verification_note='VA-verified 2026-09-08 (§7.4.1, printed p.19 (PDF p.25)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='3208a760-9b9c-4eb3-80a2-014f7c405f4d' and verification_status not in ('verified_against_standard','corrected');
-- level_of_assurance
update public.fields set verification_status='verified_against_standard', verification_quote='level of assurance degree of confidence in the declared sustainability information (3.1.4) Note 1 to entry: The levels of assurance and the conditions to achieve them can be specified in the programme (e.g. reasonable, limited). | assurance opinions shall be provided on the basis of a level of assurance (often referred to as a “reasonable level of assurance” or “limited level of assurance”). — printed pp.5, 16 (PDF pp.11, 22)', verification_note='VA-verified 2026-09-08 (§3.2.8 (with Note 1 to entry) and §6.2.2, printed pp.5, 16 (PDF pp.11, 22) — both printed passages are illustrative ("e.g.", "often referred to as"), so the two-value enum closes a list the standard leaves open (see the STAGED file)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='c4bc518b-a7f5-4ea8-8c1c-5199ab40ca9a' and verification_status not in ('verified_against_standard','corrected');
-- materiality_determined
update public.fields set verification_status='verified_against_standard', verification_quote='concept that misstatements (3.2.11), individually or aggregated, can influence the reliability of the declared sustainability information (3.1.4) and hence decisions made by the intended user (3.3.4) Note 1 to entry: Materiality can be qualitative or quantitative. — printed p.6 (PDF p.12)', verification_note='VA-verified 2026-09-08 (§3.2.10 (with Note 1 to entry), printed p.6 (PDF p.12)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='7904fdb3-d7b5-4e2f-842e-039888f5eec7' and verification_status not in ('verified_against_standard','corrected');
-- risk_assessment_done
update public.fields set verification_status='verified_against_standard', verification_quote='overall process for risk identification, risk analysis, risk evaluation and risk mitigation | risk that an assurance opinion (3.2.24) results in an inappropriate conclusion when the declared sustainability information (3.1.4) is materially misstated — printed p.6 (PDF p.12)', verification_note='VA-verified 2026-09-08 (§3.2.16 and §3.2.13, printed p.6 (PDF p.12) — Clause 3 is DEFINITIONS, not obligations; gate CR-029 anchors on §3.2.10/§3.2.16 and is correctly severity=warn (see the STAGED file)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='4fecff56-a877-409a-84b2-86260a0f8166' and verification_status not in ('verified_against_standard','corrected');

