-- independent_reviewer_assigned
update public.fields set verification_status='verified_against_standard', verification_quote='competent person, who is not a member of the validation team (3.3.14)/verification team (3.3.15), who reviews the validation or verification activities and conclusions — printed p.12 (PDF p.18)', verification_note='VA-verified 2026-09-08 (§3.3.16 (with §7.5 d)), printed p.12 (PDF p.18)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='e58f6115-e126-4171-aa03-e406ed1430f2' and verification_status not in ('verified_against_standard','corrected');
-- body_requirements_met
update public.fields set verification_status='verified_against_standard', verification_quote='e) requirements for the validation/verification body (e.g. governance, accreditation or designation by public authorities). — printed p.20 (PDF p.26)', verification_note='VA-verified 2026-09-08 (§7.5 e), printed p.20 (PDF p.26) — the printed content of the requirement is an "e.g." list; the field is a boolean attestation, so nothing is closed) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='668ca7ca-7a6b-4237-80bf-74e46779aa48' and verification_status not in ('verified_against_standard','corrected');
