-- assurance_opinion
update public.fields set verification_status='verified_against_standard', verification_quote='declaration by a validation body (3.3.6)/verification body (3.3.7) on assurance (3.2.23) in accordance with an engagement agreement | An assurance opinion is the deliverable when all validation/verification process steps are completed. The assurance opinion shall be based on validation activities or verification activities, or a mixture of validation and verification activities (i.e. a mixed engagement). — printed pp.8, 16 (PDF pp.14, 22)', verification_note='VA-verified 2026-09-08 (§3.2.24 and §6.2.1, printed pp.8, 16 (PDF pp.14, 22) — the printed §6.1.1 b) allows NON-assurance deliverables, for which §D.1.3 says the process stops before review/decision and no assurance opinion exists — yet this field is is_required=true and block gate CR-023 demands it unconditionally (see the STAGED file)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='1c7df519-3c96-410c-a5aa-cc0e293c6f67' and verification_status not in ('verified_against_standard','corrected');
-- assurance_conclusion
update public.fields set verification_status='verified_against_standard', verification_quote='Assurance opinions may be issued with conclusions that are: — unmodified (no material misstatements or limitations); — qualified (misstatements, but no material misstatement); — adverse (a material misstatement); — disclaimed (limitations or planned validation/verification activities cannot be performed). — printed p.16 (PDF p.22)', verification_note='VA-verified 2026-09-08 (§6.2.2, printed p.16 (PDF p.22) — the 4 enum values are exactly the 4 printed conclusions; §E.4.3.3 restates them. NOTE the printed verb is "may be issued", and §6.2.2 opens "Subject to the validation/verification programme" — a scope predicate block gate CR-024 drops (see the STAGED file)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='b523aa76-672c-4d24-8e2a-c53b6269ebaa' and verification_status not in ('verified_against_standard','corrected');
-- assurance_statement
update public.fields set verification_status='verified_against_standard', verification_quote='assurance statement assurance information and the assurance opinion (3.2.24) | The term “assurance statement” encompasses: a) information about the assurance engagement; and b) an opinion that includes the verifier’s or validator’s conclusion. — printed pp.8, 34 (PDF pp.14, 40)', verification_note='VA-verified 2026-09-08 (§3.2.25 (with §E.4.1), printed pp.8, 34 (PDF pp.14, 40) — the second fragment is from the INFORMATIVE Annex E and is supporting context only; the definition in §3.2.25 is the normative source) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='a00b872a-a14a-4af2-ad0f-3f63b57d94ff' and verification_status not in ('verified_against_standard','corrected');
-- non_assurance_deliverable_type
update public.fields set verification_status='verified_against_standard', verification_quote='NOTE 2 Examples of non-assurance deliverables include AUP reports, evidence reports and findings reports. | evidence report issue of results from evidence-gathering activities | findings report issue of review results from a review of evidence gathering — printed pp.7, 16 (PDF pp.13, 22)', verification_note='VA-verified 2026-09-08 (§6.1.1 NOTE 2, §3.2.21, §3.2.22, §3.2.27, printed pp.7, 16 (PDF pp.13, 22) — the printed list is EXAMPLES ("Examples of non-assurance deliverables include"), so the 3-value enum closes an open list (see the STAGED file)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='066b4a85-ff98-4bb0-9e0c-19fd274b70eb' and verification_status not in ('verified_against_standard','corrected');
-- mixed_engagement_separation
update public.fields set verification_status='verified_against_standard', verification_quote='When a mixed engagement is undertaken, the following shall apply: a) the strategic analysis and evidence-gathering plan clearly separate the elements of the declared sustainability information associated with validation from those associated with verification; b) the risk assessment clearly separates the elements of the declared sustainability information covered by the risk assessment; — printed p.17 (PDF p.23)', verification_note='VA-verified 2026-09-08 (§6.3.2 a) and b), printed p.17 (PDF p.23) — §6.3.2 is a "shall" AND gate CR-025 carries the correct printed scope predicate (it exempts non-mixed engagements) — the one gate in this encoding that models a printed conditional correctly) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='27093697-899e-4310-bf8c-d28c1cd0c1cf' and verification_status not in ('verified_against_standard','corrected');
-- deliverable_format_agreed
update public.fields set verification_status='verified_against_standard', verification_quote='If not otherwise specified in the validation/verification programme, the validation/verification body and its client shall agree on the process used to establish the deliverable and its format. This shall include, but is not limited to, the following: a) the category and format of the deliverable; b) the validation/verification process; [...] f) how facts that are discovered after the deliverable is issued are to be managed. — printed p.17 (PDF p.23)', verification_note='VA-verified 2026-09-08 (§6.4 a) to f), printed p.17 (PDF p.23) — the printed clause opens with the conditional "If not otherwise specified in the validation/verification programme" — a scope predicate block gate CR-026 drops (see the STAGED file)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='7b1fe234-cd29-4061-b846-383b0688b8ae' and verification_status not in ('verified_against_standard','corrected');
-- nonconformity_management
update public.fields set verification_status='verified_against_standard', verification_quote='nonconformity non-fulfilment of a requirement Note 1 to entry: Some programmes can require that nonconformities raised against legal requirements related to the programme are raised as non-compliances. Note 2 to entry: This document uses “specified requirements and criteria” for the word “requirement” referred to in this definition. | c) how nonconformities with specified requirements and criteria are to be managed during the validation/verification; — printed pp.8, 17 (PDF pp.14, 23)', verification_note='VA-verified 2026-09-08 (§3.2.28 and §6.4 c), printed pp.8, 17 (PDF pp.14, 23)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='21f56704-d0f6-464f-8280-01214aa9a870' and verification_status not in ('verified_against_standard','corrected');

-- ==== ISO-14019-1-08  Durchfuehrung & Konformitaet des V/V-Prozesses  (5 fields) ====
-- validation_process_standard
update public.fields set verification_status='verified_against_standard', verification_quote='Validation of declared sustainability information should be undertaken by a validation body that uses ISO 14019-3 and conforms with ISO 14019-4. — printed p.20 (PDF p.26)', verification_note='VA-verified 2026-09-08 (§8.1, printed p.20 (PDF p.26) — the printed modality is "SHOULD", not "shall" — a recommendation. ISO 14019-3 is "under preparation" at publication (footnote 2, printed p.49), so this pointer is NR (the referenced document does not exist yet)) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='32072cbc-6362-4a11-afd0-7ae25d45e875' and verification_status not in ('verified_against_standard','corrected');
-- verification_process_standard
update public.fields set verification_status='verified_against_standard', verification_quote='Verification of sustainability information should be undertaken by a verification body that uses ISO 14019-2 and conforms with ISO 14019-4. — printed p.21 (PDF p.27)', verification_note='VA-verified 2026-09-08 (§8.2, printed p.21 (PDF p.27) — the printed modality is "SHOULD", not "shall" — a recommendation) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='79391a77-cd3b-4726-b820-41c523d3f182' and verification_status not in ('verified_against_standard','corrected');
-- body_conformance_14019_4
update public.fields set verification_status='verified_against_standard', verification_quote='Validation of declared sustainability information should be undertaken by a validation body that uses ISO 14019-3 and conforms with ISO 14019-4. | Verification of sustainability information should be undertaken by a verification body that uses ISO 14019-2 and conforms with ISO 14019-4. — printed pp.20, 21 (PDF pp.26, 27)', verification_note='VA-verified 2026-09-08 (§8.1, §8.2 (with §2), printed pp.20, 21 (PDF pp.26, 27) — both printed sentences are "should"; gate CR-028 on this field is severity=warn, which is the CORRECT reading. The substantive requirements live in ISO 14019-4:2026, which is not in the library — the field is NR beyond this pointer) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='b59e8edb-f865-4192-bef2-33a02cd43c1d' and verification_status not in ('verified_against_standard','corrected');
-- conformity_decision
update public.fields set verification_status='verified_against_standard', verification_quote='Note 3 to entry: The assurance opinion for a verification (3.2.7) can be confirming or not confirming the information declared by the responsible party (3.3.3), with or without comments, according to the programme requirements. | Note 4 to entry: The assurance opinion for validation (3.2.6) can be confirming or not confirming the assumptions, limitations and methods used to develop the projected future information that is declared by the responsible party, with or without comments, according to the programme requirements. — printed p.8 (PDF p.14)', verification_note='VA-verified 2026-09-08 (§3.2.24 Notes 3 and 4 to entry, printed p.8 (PDF p.14) — the 2 enum values (confirming / not confirming) are exactly the printed pair; the printed "with or without comments" dimension is not encoded anywhere) [VA · ISO 14019-1:2026 published First edition 2026-02, PDF text layer]', verified_at=now() where id='119305ce-c3c5-402e-8672-31d5732cf531' and verification_status not in ('verified_against_standard','corrected');
