-- ==== app/project metadata exemption (2026-08-01 ruling) ====
-- engagement_id: the guideline defines "engagement" (§3.2.34, printed p.9) as the arrangement between the body and its client, but it never defines, requires or formats an identifier for it — the ID is the app’s own project key
update public.fields set verification_status='inferred_from_worksheet', verification_note='VA-pass 2026-09-08: app/project metadata - the guideline does not define this field; exempt per the 2026-08-01 metadata ruling. the guideline defines "engagement" (§3.2.34, printed p.9) as the arrangement between the body and its client, but it never defines, requires or formats an identifier for it — the ID is the app’s own project key', verified_at=now() where id in ('912ec99a-5c15-44ac-a2ef-eaadb5818266') and verification_status not in ('verified_against_standard','corrected');
